// IamAPIServer is the server API for IamAPI service.
// All implementations must embed UnimplementedIamAPIServer
// for forward compatibility.
type IamAPIServer interface {
	// Register is public self-signup, gated by
	// PlatformSettings.allow_self_registration. Not idempotent: each call
	// creates a new account.
	Register(context.Context, *RegisterRequest) (*RegisterResponse, error)
	// Login authenticates by nickname|email + password and issues a TokenPair.
	// Not idempotent: each call mints a new session/TokenPair.
	Login(context.Context, *LoginRequest) (*LoginResponse, error)
	// Refresh rotates a refresh_token into a new TokenPair. Not idempotent: the
	// refresh_token is single-use; a replay fails.
	Refresh(context.Context, *RefreshRequest) (*RefreshResponse, error)
	// Logout revokes the refresh_token's server-side session. Idempotent:
	// revoking an already-revoked session is a no-op.
	Logout(context.Context, *LogoutRequest) (*LogoutResponse, error)
	// RequestPasswordReset starts the forgot-password flow (emails a token).
	// Public. Always succeeds (no account-existence leak).
	RequestPasswordReset(context.Context, *RequestPasswordResetRequest) (*RequestPasswordResetResponse, error)
	// ConfirmPasswordReset consumes the emailed token and sets a new password.
	// Public. Not idempotent: the token is single-use.
	ConfirmPasswordReset(context.Context, *ConfirmPasswordResetRequest) (*ConfirmPasswordResetResponse, error)
	// VerifyEmail consumes an emailed verification token. Public: the token is
	// the credential and the user may be logged out.
	VerifyEmail(context.Context, *VerifyEmailRequest) (*VerifyEmailResponse, error)
	// CreateAccount is the admin-only account path (the public path is
	// Register). Not idempotent: each call creates a new account.
	CreateAccount(context.Context, *CreateAccountRequest) (*CreateAccountResponse, error)
	GetAccount(context.Context, *GetAccountRequest) (*GetAccountResponse, error)
	// GetMyAccount returns the caller's own profile — authenticated, no
	// permission (self-read).
	GetMyAccount(context.Context, *GetMyAccountRequest) (*GetMyAccountResponse, error)
	ListAccounts(context.Context, *ListAccountsRequest) (*ListAccountsResponse, error)
	// UpdateAccount is idempotent: a wholesale field set converges on retry.
	UpdateAccount(context.Context, *UpdateAccountRequest) (*UpdateAccountResponse, error)
	// DeleteAccount is idempotent: deleting an absent account is a no-op.
	DeleteAccount(context.Context, *DeleteAccountRequest) (*DeleteAccountResponse, error)
	// ChangePassword is authenticated self-service (old + new). Not idempotent.
	ChangePassword(context.Context, *ChangePasswordRequest) (*ChangePasswordResponse, error)
	// ResetPassword is the admin override (sets a new password for any account).
	// Idempotent: setting the same password twice converges.
	ResetPassword(context.Context, *ResetPasswordRequest) (*ResetPasswordResponse, error)
	// ResendVerification re-sends the caller's own email verification token.
	// Authenticated.
	ResendVerification(context.Context, *ResendVerificationRequest) (*ResendVerificationResponse, error)
	// CreateTenant is gated by PlatformSettings.allow_member_tenant_creation.
	// Not idempotent: each call creates a new tenant.
	CreateTenant(context.Context, *CreateTenantRequest) (*CreateTenantResponse, error)
	// GetTenant fetches by id or slug; slug is the routing-resolve path.
	GetTenant(context.Context, *GetTenantRequest) (*GetTenantResponse, error)
	// ListMyTenants returns the caller's tenants — authenticated, no permission.
	ListMyTenants(context.Context, *ListMyTenantsRequest) (*ListMyTenantsResponse, error)
	UpdateTenant(context.Context, *UpdateTenantRequest) (*UpdateTenantResponse, error)
	DeleteTenant(context.Context, *DeleteTenantRequest) (*DeleteTenantResponse, error)
	// TransferTenantOwnership reassigns the owner. Idempotent: transferring to
	// the current owner is a no-op.
	TransferTenantOwnership(context.Context, *TransferTenantOwnershipRequest) (*TransferTenantOwnershipResponse, error)
	// LeaveTenant drops the caller's own membership — authenticated, no
	// permission. Idempotent: leaving a tenant you are not in is a no-op.
	LeaveTenant(context.Context, *LeaveTenantRequest) (*LeaveTenantResponse, error)
	// CreateRole is not idempotent: each call creates a new role.
	CreateRole(context.Context, *CreateRoleRequest) (*CreateRoleResponse, error)
	GetRole(context.Context, *GetRoleRequest) (*GetRoleResponse, error)
	ListRoles(context.Context, *ListRolesRequest) (*ListRolesResponse, error)
	// UpdateRole is idempotent: permissions REPLACES wholesale, converging on retry.
	UpdateRole(context.Context, *UpdateRoleRequest) (*UpdateRoleResponse, error)
	DeleteRole(context.Context, *DeleteRoleRequest) (*DeleteRoleResponse, error)
	// CreateMembership is not idempotent: each call creates a new membership row.
	CreateMembership(context.Context, *CreateMembershipRequest) (*CreateMembershipResponse, error)
	GetMembership(context.Context, *GetMembershipRequest) (*GetMembershipResponse, error)
	ListMemberships(context.Context, *ListMembershipsRequest) (*ListMembershipsResponse, error)
	// UpdateMembership is idempotent: role_ids REPLACES wholesale, converging on retry.
	UpdateMembership(context.Context, *UpdateMembershipRequest) (*UpdateMembershipResponse, error)
	DeleteMembership(context.Context, *DeleteMembershipRequest) (*DeleteMembershipResponse, error)
	// GetMyPermissions resolves the caller's own permissions — authenticated, no permission.
	GetMyPermissions(context.Context, *GetMyPermissionsRequest) (*GetMyPermissionsResponse, error)
	// ListPermissions returns the grantable-permission catalog — authenticated, no permission.
	ListPermissions(context.Context, *ListPermissionsRequest) (*ListPermissionsResponse, error)
	// --- SSO: provider config (admin-only) ---
	CreateIdentityProvider(context.Context, *CreateIdentityProviderRequest) (*CreateIdentityProviderResponse, error)
	GetIdentityProvider(context.Context, *GetIdentityProviderRequest) (*GetIdentityProviderResponse, error)
	UpdateIdentityProvider(context.Context, *UpdateIdentityProviderRequest) (*UpdateIdentityProviderResponse, error)
	DeleteIdentityProvider(context.Context, *DeleteIdentityProviderRequest) (*DeleteIdentityProviderResponse, error)
	// ListIdentityProviders returns the login-page buttons. Public, read-only.
	ListIdentityProviders(context.Context, *ListIdentityProvidersRequest) (*ListIdentityProvidersResponse, error)
	// StartSSO returns the IdP authorize URL. Public. Not idempotent: each call
	// mints fresh state + PKCE stashed server-side.
	StartSSO(context.Context, *StartSSORequest) (*StartSSOResponse, error)
	// CompleteSSO is the OIDC callback. Public. Not idempotent: the code is
	// single-use and a replay fails.
	CompleteSSO(context.Context, *CompleteSSORequest) (*CompleteSSOResponse, error)
	// LinkExternalIdentity is admin-only (admin asserts the binding). Idempotent
	// on (provider, subject).
	LinkExternalIdentity(context.Context, *LinkExternalIdentityRequest) (*LinkExternalIdentityResponse, error)
	// UnlinkExternalIdentity is authenticated; the service enforces
	// account-owner-or-admin. Idempotent: unlinking an absent link is a no-op.
	UnlinkExternalIdentity(context.Context, *UnlinkExternalIdentityRequest) (*UnlinkExternalIdentityResponse, error)
	// ListExternalIdentities is authenticated; the service enforces
	// account-owner-or-admin (the "my linked logins" view).
	ListExternalIdentities(context.Context, *ListExternalIdentitiesRequest) (*ListExternalIdentitiesResponse, error)
	// CreateApiToken mints a programmatic credential; the service enforces
	// account-owner-or-admin and caps a SERVICE token to the owner's
	// permissions. Not idempotent: each call mints a new token + secret.
	CreateApiToken(context.Context, *CreateApiTokenRequest) (*CreateApiTokenResponse, error)
	// ListApiTokens lists an account's tokens (metadata only). Authenticated;
	// the service enforces account-owner-or-admin.
	ListApiTokens(context.Context, *ListApiTokensRequest) (*ListApiTokensResponse, error)
	// RevokeApiToken disables a token. Authenticated; the service enforces
	// account-owner-or-admin. Idempotent: revoking an absent/already-revoked
	// token is a no-op.
	RevokeApiToken(context.Context, *RevokeApiTokenRequest) (*RevokeApiTokenResponse, error)
	mustEmbedUnimplementedIamAPIServer()
}

